-- Commit 36097c43dd4cfc2c8ee2820cfc03c8322f314133.
CREATE TABLE meetings (meeting_id TEXT PRIMARY KEY, checkpoint TEXT NOT NULL, state TEXT);
CREATE TABLE captions (meeting_id TEXT NOT NULL REFERENCES meetings(meeting_id), sentence_key TEXT NOT NULL, fingerprint TEXT NOT NULL, body TEXT NOT NULL, PRIMARY KEY (meeting_id,sentence_key));
CREATE TABLE deliveries (sequence INTEGER PRIMARY KEY AUTOINCREMENT, meeting_id TEXT NOT NULL REFERENCES meetings(meeting_id), delivery_id TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, body TEXT NOT NULL, created_ns INTEGER NOT NULL);
CREATE INDEX deliveries_meeting ON deliveries(meeting_id,sequence);
CREATE TABLE consumers (meeting_id TEXT NOT NULL REFERENCES meetings(meeting_id), consumer_id TEXT NOT NULL, acknowledged INTEGER NOT NULL DEFAULT 0, offered INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (meeting_id,consumer_id));
CREATE TABLE attempts (meeting_id TEXT NOT NULL, consumer_id TEXT NOT NULL, sequence INTEGER NOT NULL REFERENCES deliveries(sequence) ON DELETE CASCADE, count INTEGER NOT NULL, PRIMARY KEY (meeting_id,consumer_id,sequence));
CREATE TABLE risks (meeting_id TEXT NOT NULL REFERENCES meetings(meeting_id), identity TEXT NOT NULL, body TEXT NOT NULL, PRIMARY KEY (meeting_id,identity));
CREATE TABLE sessions (app_key TEXT PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE conflicts (meeting_id TEXT NOT NULL, sentence_key TEXT NOT NULL, delivery_id TEXT PRIMARY KEY REFERENCES deliveries(delivery_id), resolved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE memberships (meeting_id TEXT PRIMARY KEY, active INTEGER NOT NULL, left_at TEXT);
CREATE TABLE tombstones (identity TEXT PRIMARY KEY, deleted_at TEXT NOT NULL);
CREATE TABLE accounting (singleton INTEGER PRIMARY KEY CHECK(singleton=1), bytes INTEGER NOT NULL);
INSERT INTO accounting(singleton,bytes) VALUES (1,0);
CREATE TRIGGER account_meetings_insert AFTER INSERT ON meetings BEGIN UPDATE accounting SET bytes=bytes+(COALESCE(length(CAST(NEW.checkpoint AS BLOB)),0) + COALESCE(length(CAST(NEW.state AS BLOB)),0)) WHERE singleton=1; END;
CREATE TRIGGER account_meetings_delete AFTER DELETE ON meetings BEGIN UPDATE accounting SET bytes=bytes+(-(COALESCE(length(CAST(OLD.checkpoint AS BLOB)),0) + COALESCE(length(CAST(OLD.state AS BLOB)),0))) WHERE singleton=1; END;
CREATE TRIGGER account_meetings_update AFTER UPDATE ON meetings BEGIN UPDATE accounting SET bytes=bytes+((COALESCE(length(CAST(NEW.checkpoint AS BLOB)),0) + COALESCE(length(CAST(NEW.state AS BLOB)),0)) - (COALESCE(length(CAST(OLD.checkpoint AS BLOB)),0) + COALESCE(length(CAST(OLD.state AS BLOB)),0))) WHERE singleton=1; END;
CREATE TRIGGER account_captions_insert AFTER INSERT ON captions BEGIN UPDATE accounting SET bytes=bytes+(COALESCE(length(CAST(NEW.body AS BLOB)),0) + COALESCE(length(CAST(NEW.sentence_key AS BLOB)),0) + COALESCE(length(CAST(NEW.fingerprint AS BLOB)),0)) WHERE singleton=1; END;
CREATE TRIGGER account_captions_delete AFTER DELETE ON captions BEGIN UPDATE accounting SET bytes=bytes+(-(COALESCE(length(CAST(OLD.body AS BLOB)),0) + COALESCE(length(CAST(OLD.sentence_key AS BLOB)),0) + COALESCE(length(CAST(OLD.fingerprint AS BLOB)),0))) WHERE singleton=1; END;
CREATE TRIGGER account_captions_update AFTER UPDATE ON captions BEGIN UPDATE accounting SET bytes=bytes+((COALESCE(length(CAST(NEW.body AS BLOB)),0) + COALESCE(length(CAST(NEW.sentence_key AS BLOB)),0) + COALESCE(length(CAST(NEW.fingerprint AS BLOB)),0)) - (COALESCE(length(CAST(OLD.body AS BLOB)),0) + COALESCE(length(CAST(OLD.sentence_key AS BLOB)),0) + COALESCE(length(CAST(OLD.fingerprint AS BLOB)),0))) WHERE singleton=1; END;
CREATE TRIGGER account_deliveries_insert AFTER INSERT ON deliveries BEGIN UPDATE accounting SET bytes=bytes+(COALESCE(length(CAST(NEW.body AS BLOB)),0) + COALESCE(length(CAST(NEW.delivery_id AS BLOB)),0)) WHERE singleton=1; END;
CREATE TRIGGER account_deliveries_delete AFTER DELETE ON deliveries BEGIN UPDATE accounting SET bytes=bytes+(-(COALESCE(length(CAST(OLD.body AS BLOB)),0) + COALESCE(length(CAST(OLD.delivery_id AS BLOB)),0))) WHERE singleton=1; END;
CREATE TRIGGER account_deliveries_update AFTER UPDATE ON deliveries BEGIN UPDATE accounting SET bytes=bytes+((COALESCE(length(CAST(NEW.body AS BLOB)),0) + COALESCE(length(CAST(NEW.delivery_id AS BLOB)),0)) - (COALESCE(length(CAST(OLD.body AS BLOB)),0) + COALESCE(length(CAST(OLD.delivery_id AS BLOB)),0))) WHERE singleton=1; END;
CREATE TRIGGER account_risks_insert AFTER INSERT ON risks BEGIN UPDATE accounting SET bytes=bytes+(COALESCE(length(CAST(NEW.body AS BLOB)),0)) WHERE singleton=1; END;
CREATE TRIGGER account_risks_delete AFTER DELETE ON risks BEGIN UPDATE accounting SET bytes=bytes+(-(COALESCE(length(CAST(OLD.body AS BLOB)),0))) WHERE singleton=1; END;
CREATE TRIGGER account_risks_update AFTER UPDATE ON risks BEGIN UPDATE accounting SET bytes=bytes+((COALESCE(length(CAST(NEW.body AS BLOB)),0)) - (COALESCE(length(CAST(OLD.body AS BLOB)),0))) WHERE singleton=1; END;
CREATE TRIGGER account_sessions_insert AFTER INSERT ON sessions BEGIN UPDATE accounting SET bytes=bytes+(COALESCE(length(CAST(NEW.body AS BLOB)),0)) WHERE singleton=1; END;
CREATE TRIGGER account_sessions_delete AFTER DELETE ON sessions BEGIN UPDATE accounting SET bytes=bytes+(-(COALESCE(length(CAST(OLD.body AS BLOB)),0))) WHERE singleton=1; END;
CREATE TRIGGER account_sessions_update AFTER UPDATE ON sessions BEGIN UPDATE accounting SET bytes=bytes+((COALESCE(length(CAST(NEW.body AS BLOB)),0)) - (COALESCE(length(CAST(OLD.body AS BLOB)),0))) WHERE singleton=1; END;
CREATE TRIGGER account_consumers_insert AFTER INSERT ON consumers BEGIN UPDATE accounting SET bytes=bytes+(COALESCE(length(CAST(NEW.consumer_id AS BLOB)),0)) WHERE singleton=1; END;
CREATE TRIGGER account_consumers_delete AFTER DELETE ON consumers BEGIN UPDATE accounting SET bytes=bytes+(-(COALESCE(length(CAST(OLD.consumer_id AS BLOB)),0))) WHERE singleton=1; END;
CREATE TRIGGER account_consumers_update AFTER UPDATE ON consumers BEGIN UPDATE accounting SET bytes=bytes+((COALESCE(length(CAST(NEW.consumer_id AS BLOB)),0)) - (COALESCE(length(CAST(OLD.consumer_id AS BLOB)),0))) WHERE singleton=1; END;
CREATE TRIGGER account_tombstones_insert AFTER INSERT ON tombstones BEGIN UPDATE accounting SET bytes=bytes+(COALESCE(length(CAST(NEW.identity AS BLOB)),0) + COALESCE(length(CAST(NEW.deleted_at AS BLOB)),0)) WHERE singleton=1; END;
CREATE TRIGGER account_tombstones_delete AFTER DELETE ON tombstones BEGIN UPDATE accounting SET bytes=bytes+(-(COALESCE(length(CAST(OLD.identity AS BLOB)),0) + COALESCE(length(CAST(OLD.deleted_at AS BLOB)),0))) WHERE singleton=1; END;
CREATE TRIGGER account_tombstones_update AFTER UPDATE ON tombstones BEGIN UPDATE accounting SET bytes=bytes+((COALESCE(length(CAST(NEW.identity AS BLOB)),0) + COALESCE(length(CAST(NEW.deleted_at AS BLOB)),0)) - (COALESCE(length(CAST(OLD.identity AS BLOB)),0) + COALESCE(length(CAST(OLD.deleted_at AS BLOB)),0))) WHERE singleton=1; END;
CREATE TRIGGER account_memberships_insert AFTER INSERT ON memberships BEGIN UPDATE accounting SET bytes=bytes+(COALESCE(length(CAST(NEW.meeting_id AS BLOB)),0) + COALESCE(length(CAST(NEW.left_at AS BLOB)),0)) WHERE singleton=1; END;
CREATE TRIGGER account_memberships_delete AFTER DELETE ON memberships BEGIN UPDATE accounting SET bytes=bytes+(-(COALESCE(length(CAST(OLD.meeting_id AS BLOB)),0) + COALESCE(length(CAST(OLD.left_at AS BLOB)),0))) WHERE singleton=1; END;
CREATE TRIGGER account_memberships_update AFTER UPDATE ON memberships BEGIN UPDATE accounting SET bytes=bytes+((COALESCE(length(CAST(NEW.meeting_id AS BLOB)),0) + COALESCE(length(CAST(NEW.left_at AS BLOB)),0)) - (COALESCE(length(CAST(OLD.meeting_id AS BLOB)),0) + COALESCE(length(CAST(OLD.left_at AS BLOB)),0))) WHERE singleton=1; END;
